package dev.eugheist.tc4modern;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.properties.NoteBlockInstrument;
import net.minecraft.world.phys.BlockHitResult;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class ArcaneEarAudit {
 static final BlockPos POS=FocalAudit.BASE.offset(20,1,64),NOTE=POS.east(5);static int ticks;static volatile boolean prepared,heard,ended;static ArcaneEar.EarEntity ear;
 static void check(boolean ok,String s){if(!ok)throw new IllegalStateException("TC4_EAR FAIL "+s);System.out.println("TC4_EAR PASS "+s);}
 static void send(net.minecraft.world.level.Level l,BlockPos pos,int tone,int note){ArcaneEar.NOTES.put(l,new ArrayList<>(List.of(new ArcaneEar.Note(pos,tone,note))));ArcaneEar.EarEntity.tick(l,POS,l.getBlockState(POS),ear);ArcaneEar.NOTES.get(l).clear();}
 static void prepare(ServerPlayer p){var l=p.serverLevel();p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.getAbilities().flying=true;p.onUpdateAbilities();p.removeAllEffects();p.getInventory().clearContent();for(var cat:thaumcraft.api.research.ResearchCategories.researchCategories.values())for(var r:cat.research.values())DevCommands.grant(p.getPersistentData(),r.key,new HashSet<>());ThaumometerItem.sync(p,"");for(int x=-3;x<=8;x++)for(int z=-3;z<=3;z++)for(int y=-1;y<=3;y++)l.setBlock(POS.offset(x,y,z),y==-1?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),2);
  l.setBlock(POS,ArcaneEar.BLOCK.get().defaultBlockState(),3);ear=(ArcaneEar.EarEntity)l.getBlockEntity(POS);ear.updateTone();check(ear.tone==1,"stone floor selects original bass drum tone");var floors=List.of(Blocks.DIRT,Blocks.STONE,Blocks.SAND,Blocks.GLASS,Blocks.OAK_PLANKS);for(int i=0;i<5;i++)check(ArcaneEar.floorTone(floors.get(i).defaultBlockState())==i,"original floor instrument "+i);
  send(l,POS.east(64),0,0);check(ear.redstoneSignal==0,"wrong instrument ignored");send(l,POS.east(64),1,1);check(ear.redstoneSignal==0,"wrong pitch ignored");send(l,POS.east(65),1,0);check(ear.redstoneSignal==0,"beyond64 blocks ignored");send(l,POS.east(64),1,0);check(ear.redstoneSignal==10,"inclusive64-block range starts10tick pulse");for(var d:Direction.values())check(l.getBlockState(POS).getSignal(l,POS,d)==15&&l.getBlockState(POS).getDirectSignal(l,POS,d)==15,"weak and strong15 output "+d);for(int i=0;i<9;i++)ArcaneEar.EarEntity.tick(l,POS,l.getBlockState(POS),ear);check(ear.redstoneSignal==1,"pulse remains after9ticks");ArcaneEar.EarEntity.tick(l,POS,l.getBlockState(POS),ear);check(ear.redstoneSignal==0&&!l.getBlockState(POS).getValue(ArcaneEar.EarBlock.ACTIVE),"pulse ends exactly at10ticks");
  ear.note=24;ArcaneEar.BLOCK.get().useWithoutItem(l.getBlockState(POS),l,POS,p,new BlockHitResult(POS.getCenter(),Direction.UP,POS,false));check(ear.note==0,"actual right click wraps pitch24 to0");ear.redstoneSignal=10;var saved=ear.saveWithFullMetadata(l.registryAccess());var copy=new ArcaneEar.EarEntity(POS,l.getBlockState(POS));copy.loadWithComponents(saved,l.registryAccess());check(copy.note==0&&copy.tone==1&&copy.redstoneSignal==0,"note tone persist, active pulse does not persist");saved.putByte("note",(byte)100);copy.loadWithComponents(saved,l.registryAccess());check(copy.note==24,"NBTpitch clamped24");ear.redstoneSignal=0;ear.notifySignal();
  var recipe=ArcaneRecipes.entries().stream().filter(e->e.key().equals("ArcaneEar")).findFirst().orElseThrow();var grid=recipe.ingredients().stream().map(i->i.getItems()[0].copy()).toList();check(recipe.matches(grid,Set.of("ARCANEEAR"))&&!recipe.matches(grid,Set.of()),"original arcane recipe research gate");
  checkMirror(p);
  l.setBlock(NOTE,Blocks.NOTE_BLOCK.defaultBlockState().setValue(NoteBlock.INSTRUMENT,NoteBlockInstrument.BASEDRUM).setValue(NoteBlock.NOTE,0),3);p.connection.teleport(POS.getX()+4,POS.getY()+3,POS.getZ()-5,35,25);p.getInventory().setItem(0,new ItemStack(ArcaneEar.BLOCK.get()));p.getInventory().selected=8;prepared=true;
 }
 static void checkMirror(ServerPlayer p){
  var r=ArcaneRecipes.entries().stream().filter(e->e.key().equals("MirrorGlass")).findFirst().orElseThrow();
  var grid=new ArrayList<ItemStack>(Collections.nCopies(9,ItemStack.EMPTY));grid.set(8,new ItemStack(net.minecraft.world.item.Items.GLASS));grid.set(0,new ItemStack(AlchemyContent.QUICKSILVER.get()));
  check(r.matches(grid,Set.of("BASICARTIFACE"))&&!r.matches(grid,Set.of()),"mirror glass shapeless recipe accepts dispersed reverse-order ingredients with research gate");
  grid.set(4,new ItemStack(Items.DIRT));check(!r.matches(grid,Set.of("BASICARTIFACE")),"shapeless recipe rejects extra ingredient");grid.set(4,ItemStack.EMPTY);grid.set(8,ItemStack.EMPTY);check(!r.matches(grid,Set.of("BASICARTIFACE")),"shapeless recipe rejects missing glass");
  p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);var wand=WandParts.make(WandParts.CAPS.get("gold"),WandParts.RODDEFS.get("greatwood"));for(var a:thaumcraft.api.aspects.Aspect.getPrimalAspects())WandData.add(wand,a,50,true);
  var table=new net.minecraft.world.SimpleContainer(10);table.setItem(9,wand);table.setItem(8,new ItemStack(Items.GLASS));table.setItem(0,new ItemStack(AlchemyContent.QUICKSILVER.get()));var menu=new ArcaneWorkbenchMenu(17,p.getInventory(),net.minecraft.world.inventory.ContainerLevelAccess.NULL,table);
  check(menu.getSlot(0).getItem().is(ArtificeDevices.MIRROR_GLASS.get())&&menu.getSlot(0).mayPickup(p),"actual workbench produces mirror glass");int fire=WandData.get(wand,thaumcraft.api.aspects.Aspect.FIRE),earth=WandData.get(wand,thaumcraft.api.aspects.Aspect.EARTH);var output=menu.getSlot(0).remove(1);menu.getSlot(0).onTake(p,output);
  check(output.is(ArtificeDevices.MIRROR_GLASS.get())&&table.getItem(0).isEmpty()&&table.getItem(8).isEmpty()&&WandData.get(wand,thaumcraft.api.aspects.Aspect.FIRE)<fire&&WandData.get(wand,thaumcraft.api.aspects.Aspect.EARTH)<earth,"actual shapeless arcane craft consumes both ingredients and vis");menu.removed(p);p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);
 }
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post event){if(!Boolean.getBoolean("tc4modern.earAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==115){check(prepared,"server setup complete");var quads=mc.getBlockRenderer().getBlockModel(mc.level.getBlockState(POS)).getQuads(mc.level.getBlockState(POS),null,net.minecraft.util.RandomSource.create());check(quads.size()==60&&quads.stream().noneMatch(q->q.getSprite().contents().name().getPath().equals("missingno")),"all ten original renderer boxes have real textures");LiquidDeathAudit.shot(mc,"arcane-ear-off.png");}if(ticks==120)server.execute(()->server.overworld().blockEvent(NOTE,Blocks.NOTE_BLOCK,0,0));if(ticks==125)server.execute(()->{check(ear.redstoneSignal>0,"actual vanilla note block event triggers ear");heard=true;});if(ticks==127){check(heard,"vanilla note received");LiquidDeathAudit.shot(mc,"arcane-ear-on.png");}if(ticks==140)server.execute(()->{check(ear.redstoneSignal==0,"actual natural pulse expired");ended=true;});if(ticks==150){check(ended,"server pulse complete");var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch("ARCANEEAR"),0);mc.setScreen(book);}if(ticks==160)LiquidDeathAudit.shot(mc,"arcane-ear-book.png");if(ticks>=170&&ticks<=220&&ticks%10==0){var keys=List.of("BASICARTIFACE","BASICARTIFACE","BASICARTIFACE","ARCTABLE","RESTABLE","TABLE");int n=(ticks-170)/10;var r=thaumcraft.api.research.ResearchCategories.getResearch(keys.get(n));check(BasicsBookRecipes.researchIcon(r.key)!=null,"actual research icon "+r.key);((ThaumonomiconScreen)mc.screen).auditOpen(r,n<3?n*2:0);}if(ticks>=175&&ticks<=225&&ticks%10==5)LiquidDeathAudit.shot(mc,"artifice-base-book-"+(ticks-175)/10+".png");if(ticks==230)mc.stop();}
}
